What docs?  I am thinking this is a simple custom tool.  I could implement in a few minutes but I don't know what you're referring to by "docs."

```js
import { tool } from "@opencode-ai/plugin";
import { exec } from 'node:child_process';
import { promisify } from 'node:util';
import process from 'node:process';

const execAsync = promisify(exec);

export default tool({
  description: "Open a URL in the user's default browser",

  args: {
    url: tool.schema
      .string()
      .url()
      .describe("The URL to open in the browser"),
  },
  async execute(args) {
    const url = args.url;

    let command;
    if (process.platform === 'darwin') {
      command = `open "${url}"`;
    } else if (process.platform === 'win32') {
      command = `start "${url}"`;
    } else {
      command = `xdg-open "${url}"`;
    }

    try {
      await execAsync(command);
      return JSON.stringify({ success: true, url, message: `Opened ${url} in your default browser` });
    } catch (error) {
      return JSON.stringify({ success: false, url, error: error.message });
    }
  },
});

```

